  + pick_up_date : date
}

class Rental {
  + return_date : date
}

Client "1" -- "*" Reservation : makes
BicycleModel "1" -- "*" Reservation : requested_in
Store "1" -- "*" Reservation : at_pickup
Reservation "1" -- "0..1" Rental : becomes
Bicycle "1" -- "0..1" Rental : is_rented_in
Bicycle "*" -- "1" BicycleModel : is_a
Bicycle "1" -- "1" Store : stored_at
Rental "*" -- "1" Store : returned_to

